-- UNAPPLIED local UTC scaffold; CLI unavailable. Manual node/route references, not execution.
create table portal_private.crm_node_route_history(id uuid primary key,project_id uuid not null references public.projects,node_id uuid not null references public.crm_nodes,sequence integer not null,previous_id uuid references portal_private.crm_node_route_history,action text not null check(action in ('Linked','Unlinked')),route_id uuid not null references portal_private.crm_project_routes,route_version uuid not null references portal_private.crm_project_route_versions,node_source jsonb not null,route_source jsonb not null,reason text not null,actor_id uuid not null references public.profiles,created_at timestamptz not null default now(),payload jsonb not null,unique(node_id,sequence));
create index crm_node_route_history_project on portal_private.crm_node_route_history(project_id);
create index crm_node_route_history_previous on portal_private.crm_node_route_history(previous_id);
create index crm_node_route_history_route on portal_private.crm_node_route_history(route_id);
create index crm_node_route_history_version on portal_private.crm_node_route_history(route_version);
create index crm_node_route_history_actor on portal_private.crm_node_route_history(actor_id);
alter table portal_private.crm_node_route_history enable row level security;
revoke all on portal_private.crm_node_route_history from public,anon,authenticated,service_role;
create trigger crm_node_route_history_immutable before update or delete on portal_private.crm_node_route_history for each row execute function portal_private.lead_api_evidence_immutable();
create function public.project_node_route_context(p_project uuid default null,p_node uuid default null) returns jsonb language plpgsql stable security definer set search_path='' as $$declare c jsonb;n public.crm_nodes;h portal_private.crm_node_route_history;begin
 c:=public.project_route_context(p_project);
 if p_project is null then if p_node is not null then raise exception 'Actual node project required';end if;return jsonb_build_object('projects',c->'projects');end if;
 if p_node is not null then select * into n from public.crm_nodes where id=p_node and project_id=p_project;if not found then raise exception 'Actual node in selected project required';end if;select * into h from portal_private.crm_node_route_history where node_id=p_node and project_id=p_project order by sequence desc limit 1;end if;
 return jsonb_build_object('project',c->'project','can_edit',(c->'project'->>'status')<>'Completed' and not exists(select 1 from public.crm_phases where project_id=p_project and status<>'Draft') and not exists(select 1 from public.crm_handovers where project_id=p_project and status in ('Awaiting signatures','Signed','Closed')),'nodes',coalesce((select jsonb_agg(jsonb_build_object('id',id,'device_id',device_id,'version',version) order by device_id,id) from public.crm_nodes where project_id=p_project),'[]'),'routes',coalesce((select jsonb_agg(to_jsonb(v)-'payload' order by r.code,r.id) from portal_private.crm_project_routes r join portal_private.crm_project_route_versions v on v.route_id=r.id and v.revision=r.revision where r.project_id=p_project and v.state='Active'),'[]'),'node',case when n.id is not null then to_jsonb(n) else null end,'history',coalesce((select jsonb_agg(to_jsonb(x)-'payload' order by sequence desc) from portal_private.crm_node_route_history x where node_id=p_node and project_id=p_project),'[]'),'current_link',case when h.id is not null then to_jsonb(h)-'payload' else null end,'matches_current_sources',coalesce(h.action='Linked' and h.node_source=to_jsonb(n) and exists(select 1 from portal_private.crm_project_routes r join portal_private.crm_project_route_versions v on v.route_id=r.id and v.revision=r.revision where r.id=h.route_id and r.project_id=p_project and v.id=h.route_version and v.state='Active' and h.route_source=to_jsonb(v)-'payload'),false));
end$$;
create function public.save_node_route_link(p_request uuid,p_project uuid,p_node uuid,p_previous uuid,p_action text,p_route uuid,p_node_source jsonb,p_route_source jsonb,p_reason text,p_confirm boolean) returns uuid language plpgsql security definer set search_path='' as $$declare n public.crm_nodes;r portal_private.crm_project_routes;v portal_private.crm_project_route_versions;previous portal_private.crm_node_route_history;receipt portal_private.crm_node_route_history;payload jsonb;actual_route_source jsonb;actual_route uuid;actual_route_version uuid;project_status text;begin
 perform 1 from public.profiles where id=auth.uid() and active and role in ('admin','team') for share;if not found then raise exception 'Current node/route authority required';end if;
 perform 1 from public.crm_memberships where user_id=auth.uid() order by role_id,team_id for share;perform 1 from public.crm_roles order by id for share;perform 1 from public.crm_teams where id in(select team_id from public.crm_memberships where user_id=auth.uid()) order by id for share;
 if p_request is null or p_project is null or p_node is null then raise exception 'Actual project node and request required';end if;
 perform pg_advisory_xact_lock(hashtextextended('node-route-link:'||p_request,0));select status into project_status from public.projects where id=p_project for update;
 if not found or not portal_private.project_criteria_access(p_project) then raise exception 'Current actual Admin or assigned PM required after waiting';end if;
 select * into n from public.crm_nodes where id=p_node and project_id=p_project for share;if not found then raise exception 'Actual node must belong to selected project';end if;
 payload:=jsonb_build_object('project',p_project,'node',p_node,'previous',p_previous,'action',p_action,'route',p_route,'node_source',p_node_source,'route_source',p_route_source,'reason',p_reason,'confirmed',p_confirm);
 select * into receipt from portal_private.crm_node_route_history where id=p_request;
 if found then if receipt.actor_id<>auth.uid() or receipt.payload is distinct from payload then raise exception 'Node/route retry meaning changed';end if;return receipt.id;end if;
 if project_status='Completed' or exists(select 1 from public.crm_phases where project_id=p_project and status<>'Draft') or exists(select 1 from public.crm_handovers where project_id=p_project and status in ('Awaiting signatures','Signed','Closed')) then raise exception 'Phase review, completed project or released handover keeps node/route links read-only';end if;
 if p_confirm is distinct from true or p_action is null or p_action not in ('Linked','Unlinked') or length(trim(coalesce(p_reason,''))) not between 3 and 1000 or p_node_source is distinct from to_jsonb(n) then raise exception 'Exact current node, actual link action, reason and confirmation required';end if;
 select * into previous from portal_private.crm_node_route_history where node_id=p_node order by sequence desc limit 1;
 if p_previous is distinct from previous.id or previous.project_id is not null and previous.project_id<>p_project then raise exception 'Node route history/project changed; refresh latest reference';end if;
 if p_action='Linked' then
 select * into r from portal_private.crm_project_routes where id=p_route and project_id=p_project for share;
 if not found then raise exception 'Actual route must belong to selected project';end if;
 select * into v from portal_private.crm_project_route_versions where route_id=r.id and revision=r.revision;
 if v.state is distinct from 'Active' or p_route_source is distinct from to_jsonb(v)-'payload' then raise exception 'Current Active route revision changed; refresh selected source';end if;
 actual_route:=r.id;actual_route_version:=v.id;actual_route_source:=to_jsonb(v)-'payload';
 else
 if previous.action is distinct from 'Linked' or p_route is not null or p_route_source is not null then raise exception 'Unlink must explicitly target latest saved reference without a new route';end if;
 actual_route:=previous.route_id;actual_route_version:=previous.route_version;actual_route_source:=previous.route_source;
 end if;
 insert into portal_private.crm_node_route_history(id,project_id,node_id,sequence,previous_id,action,route_id,route_version,node_source,route_source,reason,actor_id,payload) values(p_request,p_project,p_node,coalesce(previous.sequence,0)+1,previous.id,p_action,actual_route,actual_route_version,to_jsonb(n),actual_route_source,trim(p_reason),auth.uid(),payload);return p_request;
end$$;
revoke all on function public.project_node_route_context(uuid,uuid),public.save_node_route_link(uuid,uuid,uuid,uuid,text,uuid,jsonb,jsonb,text,boolean) from public,anon,service_role;
grant execute on function public.project_node_route_context(uuid,uuid),public.save_node_route_link(uuid,uuid,uuid,uuid,text,uuid,jsonb,jsonb,text,boolean) to authenticated;
